#[derive(Debug, Clone, PartialEq)]
enum Cargo {
    Rum(u32),
    Gold(u32),
    Map(String),
}

#[derive(Debug, Clone, PartialEq)]
struct Doubloons(u32);

#[derive(Debug, Clone, PartialEq)]
struct Ship {
    name: String,
    hold: Vec<Cargo>,
}

impl Ship {
    fn new(name: &str) -> Ship {
        Ship {
            name: name.to_string(),
            hold: Vec::new(),
        }
    }

    fn load(&mut self, cargo: Cargo) {
        self.hold.push(cargo);
    }

    fn rum(&self) -> u32 {
        let mut total = 0;
        for cargo in &self.hold {
            if let Cargo::Rum(n) = cargo {
                total += n;
            }
        }
        total
    }

    fn gold(&self) -> Doubloons {
        let mut total = 0;
        for cargo in &self.hold {
            if let Cargo::Gold(n) = cargo {
                total += n;
            }
        }
        Doubloons(total)
    }

    fn first_map(&self) -> Option<&str> {
        for cargo in &self.hold {
            if let Cargo::Map(place) = cargo {
                return Some(place);
            }
        }
        None
    }

    fn scuttle(self) -> Vec<String> {
        let mut maps = Vec::new();
        for cargo in self.hold {
            if let Cargo::Map(place) = cargo {
                maps.push(place);
            }
        }
        maps
    }
}

fn main() {
    let mut ship = Ship::new("Gull");
    ship.load(Cargo::Rum(4));
    ship.load(Cargo::Map(String::from("Skull Isle")));
    ship.load(Cargo::Gold(30));
    println!("{}: {} rum, {:?}", ship.name, ship.rum(), ship.gold());
    println!("first map: {:?}", ship.first_map());
    println!("salvaged: {:?}", ship.scuttle());
}

