#[derive(Debug, Clone, PartialEq)]
enum Order {
    Sail { heading: String, knots: u32 },
    Fire { guns: u32 },
    Signal(String),
    Anchor,
}

fn call_out(order: &Order) -> String {
    match order {
        Order::Sail { heading, knots: 0 } => format!("drift toward {heading}"),
        Order::Sail { heading, knots } if *knots >= 20 => format!("full speed to {heading}!"),
        Order::Sail { heading, knots } => format!("sail to {heading} at {knots} knots"),
        Order::Fire { guns: 0 } => String::from("hold fire"),
        Order::Fire { guns: 1 } => String::from("fire 1 gun"),
        Order::Fire { guns } => format!("fire {guns} guns"),
        Order::Signal(text) if text.is_empty() => String::from("(silence)"),
        Order::Signal(text) => format!("signal: {text}"),
        Order::Anchor => String::from("drop anchor"),
    }
}

fn main() {
    let orders = [
        Order::Sail {
            heading: String::from("Tortuga"),
            knots: 8,
        },
        Order::Fire { guns: 3 },
        Order::Signal(String::from("land ho")),
        Order::Anchor,
    ];
    for order in &orders {
        println!("{}", call_out(order));
    }
}

