use std::io::{self, Read};

#[derive(Debug, Clone, PartialEq)]
enum Cargo {
    Rum(u32),
    Gold(u32),
    Map(String),
}

#[derive(Debug, Clone, PartialEq)]
enum Order {
    Load(Cargo),
    Sail(String),
    Fire(u32),
    Unload,
}

#[derive(Debug)]
struct Ship {
    name: String,
    port: String,
    hold: Vec<Cargo>,
    shots: u32,
}

/// "12 rum", "5 gold" or "map to Skull-Isle".
fn describe(cargo: &Cargo) -> String {
    match cargo {
        Cargo::Rum(n) => format!("{n} rum"),
        Cargo::Gold(n) => format!("{n} gold"),
        Cargo::Map(place) => format!("map to {place}"),
    }
}

/// One trimmed, non-empty line into an order, or None if it is invalid.
fn parse_order(line: &str) -> Option<Order> {
    let words: Vec<&str> = line.split_whitespace().collect();
    let order = match words.as_slice() {
        ["load", "rum", n] => {
            let Ok(n) = n.parse() else {
                return None;
            };
            Order::Load(Cargo::Rum(n))
        }
        ["load", "gold", n] => {
            let Ok(n) = n.parse() else {
                return None;
            };
            Order::Load(Cargo::Gold(n))
        }
        ["load", "map", place] => Order::Load(Cargo::Map(place.to_string())),
        ["sail", place] => Order::Sail(place.to_string()),
        ["fire", n] => {
            let Ok(n) = n.parse() else {
                return None;
            };
            Order::Fire(n)
        }
        ["unload"] => Order::Unload,
        _ => return None,
    };
    Some(order)
}

impl Ship {
    fn new(name: &str, port: &str) -> Self {
        Ship {
            name: name.to_string(),
            port: port.to_string(),
            hold: Vec::new(),
            shots: 0,
        }
    }

    fn apply(&mut self, order: Order) -> String {
        match order {
            Order::Load(cargo) => {
                let line = format!("loaded {}", describe(&cargo));
                self.hold.push(cargo);
                line
            }
            Order::Sail(place) if place == self.port => format!("already in {place}"),
            Order::Sail(place) => {
                let line = format!("sailed to {place}");
                self.port = place;
                line
            }
            Order::Fire(0) => String::from("held fire"),
            Order::Fire(n) => {
                self.shots += n;
                format!("fired {n}")
            }
            Order::Unload => match self.hold.pop() {
                Some(cargo) => format!("unloaded {}", describe(&cargo)),
                None => String::from("hold is empty"),
            },
        }
    }

    fn report(&self) -> String {
        let (mut rum, mut gold, mut maps) = (0, 0, 0);
        for cargo in &self.hold {
            match cargo {
                Cargo::Rum(n) => rum += n,
                Cargo::Gold(n) => gold += n,
                Cargo::Map(_) => maps += 1,
            }
        }
        format!(
            "{} in {} | rum {rum} | gold {gold} | maps {maps} | shots {}",
            self.name, self.port, self.shots
        )
    }
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let mut ship = Ship::new("Crab Queen", "Tortuga");
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match parse_order(line) {
            Some(order) => println!("{}", ship.apply(order)),
            None => println!("? {line}"),
        }
    }
    println!("{}", ship.report());
}
